import React, { Component } from 'react'
import { connect } from 'react-redux'
import { DoneWrapper } from './component.style'
import { Result, Button } from 'antd'

class Done extends Component {
  onClickShowDetail = () => {
    const { createRecon } = this.props
    this.props.history.push(`lists/${createRecon.id}`)
  }

  render () {
    return (
      <DoneWrapper>
        <Result
          status='success'
          title='Recon request created successfully!'
          extra={[
            <Button
              type='primary'
              onClick={this.onClickShowDetail}
            >
              View Recon Details
            </Button>,
            <Button onClick={() => this.props.resetData()}>
              Create Another Recon Request
            </Button>
          ]}
        />
      </DoneWrapper>
    )
  }
}

export default connect(state => ({
  createRecon: state.Recon.createRecon
}), {

})(Done)
