import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Form, Card, Steps, Icon, Button } from 'antd'
import { CreateReconStyle } from './pages/component.style'
import ReconActions from '../../../../redux/recon/actions'
import PolicyActions from '../../../../../redux/policy/actions'
import BasicForm from './pages/basicForm'
import FileTemplateList from './pages/listTemplate'
import DetailForm from './pages/detailForm'
import DonePage from './pages/done'
import UserActions from '../../../../redux/user/actions'
import PromoActions from '../../../../redux/promo/actions'
import loadingAction from '../../../../../redux/loading/actions'
import ErrorAction from '../../../../../redux/error/actions'

const {
  createRecon, uploadReconFiles,
  generateSignedUrl, reconUploadFile
} = ReconActions
const { getProducts, getPartners } = PolicyActions
const { getInternalUsers } = UserActions
const { getPackageList } = PromoActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction

const { Step } = Steps

const initialState = {
  current: 0,
  templateId: '',
  stepsConfig: [
    { title: 'Basic Form', status: 'process', icon: 'form' },
    { title: 'Choose Template', status: 'wait', icon: 'container' },
    { title: 'Fill Details', status: 'wait', icon: 'snippets' },
    { title: 'Done', status: 'wait', icon: 'smile-o' }
  ],
  partner: '',
  product: ''
}

class CreateRecon extends Component {
  constructor(props) {
    super(props)
    this.state = initialState
  }

  componentDidMount() {
    const { partners } = this.props
    if (partners.length < 1) {
      this.props.getPartners()
    }
    this.props.getProducts()
    this.props.getInternalUsers()
  }

  nextStep = (id) => {
    const { current, stepsConfig } = this.state
    const tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'finish'
    tempStepsConfig[current + 1].status = 'process'
    this.setState({ stepsConfig: tempStepsConfig, current: current + 1 })
    if (id) {
      this.setState({ templateId: id })
    }
  }

  handlePrevious = () => {
    const { current, stepsConfig } = this.state
    const tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'wait'
    tempStepsConfig[current - 1].status = 'process'
    this.setState({ stepsConfig: tempStepsConfig, current: current - 1 })
  }

  stepStateChange = (state) => {
    const { current, stepsConfig } = this.state
    const tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = state
    this.setState({ stepsConfig: tempStepsConfig })
  }

  resetData = () => {
    this.setState(initialState)
  }

  saveTemplate = (partner, product) => {
    this.setState({ partner, product })
  }

  render() {
    const {
      history
    } = this.props
    const { current, stepsConfig, templateId, partner, product } = this.state

    return (
      <CreateReconStyle>
        <Card>
          <div className='heading'>Create Recon</div>
          <Steps current={current}>
            {
              stepsConfig.map(({ title, status, icon }, index) => <Step key={index} status={status} title={title} icon={<Icon type={icon} />} />)
            }
          </Steps>
          {
            current === 0 &&
            <Card>
              <BasicForm
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
              />
            </Card>
          }
          {
            current === 1 &&
            <Card>
              <FileTemplateList
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                saveTemplate={this.saveTemplate}
              />
            </Card>
          }
          {
            current === 2 &&
            <Card>
              <DetailForm
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                templateId={templateId}
                partner={partner}
                product={product}
              />
            </Card>
          }
          {
            current === 3 &&
            <Card>
              <DonePage
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                history={history}
                resetData={this.resetData}
              />
            </Card>
          }
          {
            current !== 0 && current !== 3 &&
            <Button onClick={this.handlePrevious} className='back-button'>
              Back
            </Button>
          }
        </Card>
      </CreateReconStyle>
    )
  }
}

const WrappedCreateRecon = Form.create()(CreateRecon)

export default connect(
  state => ({
    partners: state.Policy.partners,
    products: state.Policy.products,
    internalUsers: state.User.internalUsers,

    partnersLoading: state.Loading.GET_PARTNERS,
    partnersError: state.Error.GET_PARTNERS,

    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,

    internalUsersLoading: state.Loading.GET_INTERNAL_USERS,
    internalUsersError: state.Error.GET_INTERNAL_USERS,

    postCreateReconLoading: state.Loading.POST_CREATE_RECON,
    postCreateReconError: state.Error.POST_CREATE_RECON,
    postCreateReconMessage: state.Recon.postCreateReconMessage,

    packageList: state.PromoDetails.packageLists,
    packageListLoading: state.Loading.GET_COUPON_PACKAGE_LIST,
    packageListError: state.Error.GET_COUPON_PACKAGE_LIST,

    generateSignedUrlLoading: state.Loading.GENERATE_SIGNED_URL,
    generateSignedUrlError: state.Error.GENERATE_SIGNED_URL,
    generateSignedUrlStatus: state.Recon.signedUrlStatus,
    signedUrl: state.Recon.signedUrl,

    uploadFilesLoading: state.Loading.RECON_FILE_UPLOAD,
    uploadFilesError: state.Error.RECON_FILE_UPLOAD,
    failedFileData: state.Recon.failedFileData
  }),
  {
    getPartners,
    getProducts,
    getPackageList,
    getInternalUsers,
    createRecon,
    uploadReconFiles,
    resetLoadingRedux,
    resetErrorRedux,
    generateSignedUrl,
    reconUploadFile
  }
)(WrappedCreateRecon)
