import React, { Component } from 'react'
import { connect } from 'react-redux'
import { FileTemplateWrapper } from './component.style'
import { Radio, Row, Button, notification } from 'antd'
import { get } from 'lodash'

class ListTemplate extends Component {
  state = {
    templateId: '',
    partner: '',
    product: ''
  }

  handleNext = () => {
    const { templateId, partner, product } = this.state

    if (templateId !== '') {
      this.props.nextStep(templateId)
      this.props.saveTemplate(partner, product)
    } else {
      notification['error']({ message: 'Please select Template to continue' })
    }
  }

  handleChange = (e) => {
    const value = e.target.value
    const template = JSON.parse(value)
    this.setState({ templateId: template.id, partner: template.partner, product: template.product })
  }

  render () {
    const { fileTemplates } = this.props

    return (
      <FileTemplateWrapper>
        <Radio.Group onChange={this.handleChange}>
          {
            fileTemplates.map(template =>
              <Row key={template.id} type='flex' align='middle'>
                <Radio value={JSON.stringify(template)} />
                <div className='template-container'>
                  <div className='template-header'>{template.name.toUpperCase()}</div>
                  <div className='template-content'><span className='head'>Partner -</span> {template.partner}</div>
                  <div className='template-content'><span className='head'>Product -</span> {get(template, 'display_name', []).join(', ')}</div>
                  <div className='template-content'><span className='head'>Package -</span> {template.package || 'All'}</div>
                </div>
              </Row>
            )
          }
        </Radio.Group>
        <Row type='flex' justify='end'>
          <Button
            type='primary'
            onClick={this.handleNext}
          >
            Next
          </Button>
        </Row>
      </FileTemplateWrapper>
    )
  }
}

export default connect(
  state => ({
    fileTemplates: state.Recon.fileTemplates
  }),
  {

  }
)(ListTemplate)
