import React, { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import {
  Form,
  Icon,
  Input,
  Button,
  Select,
  Spin,
  Upload,
  DatePicker,
  notification,
  Row
} from 'antd'
import ReconActions from '../../../../../redux/recon/actions'
import PolicyActions from '../../../../../../redux/policy/actions'
import UserActions from '../../../../../redux/user/actions'
import PromoActions from '../../../../../redux/promo/actions'
import { DetailFormWrapper } from './component.style'
import loadingAction from '../../../../../../redux/loading/actions'
import ErrorAction from '../../../../../../redux/error/actions'

const Option = Select.Option
const Dragger = Upload.Dragger

const { createRecon, resetReduxStateRecon, uploadReconFiles,
  generateSignedUrl, reconUploadFile
} = ReconActions
const { getProducts } = PolicyActions
const { getInternalUsers } = UserActions
const { getPackageList } = PromoActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction

class DetailForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
      uploadedFiles: [],
      uploadFileLoading: false,
      count: 0
    }
  }

  componentDidMount () {
    // this.props.getInternalUsers()
    this.props.resetLoadingRedux(['POST_CREATE_RECON', 'GENERATE_SIGNED_URL', 'RECON_FILE_UPLOAD'])
    this.props.resetErrorRedux(['POST_CREATE_RECON', 'GENERATE_SIGNED_URL', 'RECON_FILE_UPLOAD'])
  }

  componentWillReceiveProps (nextProps) {
    const {
      postCreateReconLoading, postCreateReconError,
      postCreateReconMessage
    } = nextProps
    const { uploadedFiles, count } = this.state

    if (postCreateReconLoading === false) {
      const isError = !!postCreateReconError
      const notificationType = isError ? 'error' : 'success'

      if (!isError) {
        // this.props.fetchReconList()
        this.props.nextStep()
      }

      notification[notificationType]({
        title: notificationType,
        message: postCreateReconMessage
      })
      this.props.resetLoadingRedux(['POST_CREATE_RECON'])
      this.props.resetErrorRedux(['POST_CREATE_RECON'])
      this.props.resetReduxStateRecon(['postCreateReconMessage'])
    }

    if (nextProps.generateSignedUrlLoading === false) {
      if (nextProps.generateSignedUrlError === false) {
        let lastIndex = -1
        uploadedFiles.forEach((el, index) => { 
          const filenameWithoutExt = el.filename.replace(/\.[^/.]+$/, '')
          if (nextProps.signedUrl['filename']?.includes(filenameWithoutExt)) { 
            lastIndex = index 
          } 
        })
        if (lastIndex !== -1) {
          const fileObject = uploadedFiles[lastIndex].file
          const updatedFile = { ...uploadedFiles[lastIndex], ...nextProps.signedUrl, file: fileObject }
          const newUploadedFiles = [...uploadedFiles]
          newUploadedFiles[lastIndex] = updatedFile
          this.setState({ uploadedFiles: newUploadedFiles })
          this.props.reconUploadFile({
            url: nextProps.signedUrl.signed_url,
            file: fileObject
          })
        } else {
          this.setState({ uploadFileLoading: false })
        }
      } else {
        notification['error']({ message: nextProps.generateSignedUrlStatus })
        this.setState({ uploadFileLoading: false })
      }
      this.props.resetLoadingRedux(['GENERATE_SIGNED_URL'])
      this.props.resetErrorRedux(['GENERATE_SIGNED_URL'])
    }

    if (nextProps.uploadFilesLoading === false && nextProps.uploadFilesError) {
      notification['error']({ message: 'Error occured while uploading file.' })
      this.removeFile(nextProps.failedFileData.url)
      this.props.resetLoadingRedux(['RECON_FILE_UPLOAD'])
      this.props.resetErrorRedux(['RECON_FILE_UPLOAD'])
    }
    if (nextProps.uploadFilesLoading === false && nextProps.uploadFilesError === false) {
      this.setState({ uploadFileLoading: !(uploadedFiles.length === count + 1), count: count + 1 })
      this.props.resetLoadingRedux(['RECON_FILE_UPLOAD'])
      this.props.resetErrorRedux(['RECON_FILE_UPLOAD'])
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { templateId, partner, product } = this.props
        const { uploadedFiles } = this.state
        const {
          from_date: fromDate,
          to_date: toDate
        } = values

        delete values['file']
        const fromDateString = fromDate.format('YYYY-MM-DD')
        const toDateString = toDate.format('YYYY-MM-DD')

        // values['package_code'] = values['package_code'].join(',')
        const processedFiles = uploadedFiles
          .filter(file => file.url)
          .map(file => ({ ...file, url: file.url }))
          
        if (processedFiles.length === 0) {
          notification['error']({ message: 'Please wait for files to finish uploading' })
          return
        }

        let payload = {
          ...values,
          from_date: fromDateString,
          to_date: toDateString,
          report_recipients: values['report_recipients'].toString(),
          files: processedFiles,
          templateId,
          partner,
          product
        }

        this.props.createRecon({
          body: payload
        })
      }
    })
  }

  changeValidFrom = (date, dateString) => {
    this.setState({
      validFrom: dateString,
      validToEnable: true
    }, this.props.form.resetFields(['to_date']))
  }

  changeValidTo = (date, dateString) => {
    this.setState({ validTo: dateString })
  }

  disabledValidTo = current => (current < moment(this.state.validFrom)) || (current > moment())

  disabledDate = current => current && current > moment()

  onFileChange = info => {
    const { partner, product } = this.props
    const { uploadedFiles } = this.state
    const { file } = info
    const formData = {}
    // const formData = new FormData()
    // formData.append('file', originFileObj)
    formData['name'] = file.name
    formData['size'] = file.size
    formData['type'] = file.type
    this.setState({ uploadFileLoading: true })
    this.setState({ uploadedFiles: [...uploadedFiles, { filename: file.name, file: file.originFileObj }] })
    this.props.generateSignedUrl({
      formData,
      partner,
      product
    })
  }

  removeFile = (name) => {
    const { uploadedFiles, count } = this.state
    const fileList = uploadedFiles.filter(item => item['url'] && !item['url'].includes(name))

    this.setState({
      uploadedFiles: fileList,
      count: count - 1
    })
  }

  render () {
    const {
      internalUsers,
      internalUsersLoading,
      postCreateReconLoading, form
    } = this.props
    const {
      validFrom, uploadedFiles, uploadFileLoading
    } = this.state
    const { getFieldDecorator } = form
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 4 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 16 }
      }
    }

    return (
      <DetailFormWrapper>
        <Spin spinning={!!postCreateReconLoading}>
          <Form onSubmit={this.handleSubmit} className='login-form' {...formItemLayout}>
            <Form.Item label='Recon Name'>
              {getFieldDecorator('recon_name', {
                rules: [{ required: true, message: 'Please input recon title!' }]
              })(
                <Input
                  placeholder='Recon Name'
                />
              )}
            </Form.Item>
            <Form.Item label='Report Recipients'>
              {getFieldDecorator('report_recipients', {
                rules: [{ required: true, message: 'Please choose report recipients!' }]
              })(
                <Select
                  placeholder='Report Recipients'
                  mode='multiple'
                  showSearch
                  filterOption={(input, option) => option.props.value.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                  loading={!!internalUsersLoading}
                  disabled={!!internalUsersLoading}
                >
                  {internalUsers.map(({ email, name }) =>
                    <Option value={email} key={email}>{name ? `${name}-${email}` : email}</Option>)}
                </Select>
              )}
            </Form.Item>
            <Form.Item label='From Date'>
              {getFieldDecorator('from_date', {
                rules: [{ required: true, message: 'Please select from date!' }]
              })(
                <DatePicker
                  format={'YYYY-MM-DD'}
                  onChange={this.changeValidFrom}
                  placeholder='From Date'
                  disabledDate={this.disabledDate}
                />
              )}
            </Form.Item>
            <Form.Item label='To Date'>
              {getFieldDecorator('to_date', {
                rules: [{ required: true, message: 'Please select To Date!' }]
              })(
                <DatePicker
                  format={'YYYY-MM-DD'}
                  disabledDate={this.disabledValidTo}
                  disabled={!validFrom}
                  onChange={this.changeValidTo}
                  placeholder='To Date'
                />
              )}
            </Form.Item>
            <Form.Item label='Upload File'>
              {getFieldDecorator('file', {
                rules: [{ required: true, message: 'Please select file!' }]
              })(
                <Dragger
                  customRequest={() => true}
                  showUploadList={false}
                  multiple
                  accept='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,.csv'
                  onChange={this.onFileChange}
                >
                  <p className='ant-upload-drag-icon'>
                    <Icon type='inbox' />
                  </p>
                  <p>
                    {'Click or drag file to this area to upload'}
                  </p>
                </Dragger>
              )}
            </Form.Item>

            <Spin spinning={!!uploadFileLoading}>
              {
                uploadedFiles && uploadedFiles.map(item =>
                  <div key={item.filename}>
                    <Row type='flex'>
                      <p className='ant-upload-text'>{item.filename}</p>
                      <span className='remove-image' onClick={() => this.removeFile(item.url)}>X</span>
                    </Row>
                  </div>
                )
              }
            </Spin>
            {/* <Form.Item> */}
            <Row type='flex' justify='end'>
              <Button disabled={uploadFileLoading} type='primary' htmlType='submit' className='login-form-button'>
                Submit
              </Button>
            </Row>
            {/* </Form.Item> */}
          </Form>
        </Spin>
      </DetailFormWrapper>
    )
  }
}

const WrappedDetailForm = Form.create()(DetailForm)

export default connect(
  state => ({
    partners: state.Policy.partners,
    products: state.Policy.products,
    internalUsers: state.User.internalUsers,

    partnersLoading: state.Loading.GET_PARTNERS,
    partnersError: state.Error.GET_PARTNERS,

    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,

    internalUsersLoading: state.Loading.GET_INTERNAL_USERS,
    internalUsersError: state.Error.GET_INTERNAL_USERS,

    postCreateReconLoading: state.Loading.POST_CREATE_RECON,
    postCreateReconError: state.Error.POST_CREATE_RECON,
    postCreateReconMessage: state.Recon.postCreateReconMessage,

    packageList: state.PromoDetails.packageLists,
    packageListLoading: state.Loading.GET_COUPON_PACKAGE_LIST,
    packageListError: state.Error.GET_COUPON_PACKAGE_LIST,

    generateSignedUrlLoading: state.Loading.GENERATE_SIGNED_URL,
    generateSignedUrlError: state.Error.GENERATE_SIGNED_URL,
    generateSignedUrlStatus: state.Recon.signedUrlStatus,
    signedUrl: state.Recon.signedUrl,

    uploadFilesLoading: state.Loading.RECON_FILE_UPLOAD,
    uploadFilesError: state.Error.RECON_FILE_UPLOAD,
    failedFileData: state.Recon.failedFileData
  }),
  {
    resetReduxStateRecon,
    getProducts,
    getPackageList,
    getInternalUsers,
    createRecon,
    uploadReconFiles,
    resetLoadingRedux,
    resetErrorRedux,
    generateSignedUrl,
    reconUploadFile
  }
)(WrappedDetailForm)
