import React, { Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { get, map } from 'lodash'
import {
  Form,
  Button,
  Select,
  Spin,
  Row,
  notification
} from 'antd'
import ReconActions from '../../../../../redux/recon/actions'
import PolicyActions from '../../../../../../redux/policy/actions'
import PromoActions from '../../../../../redux/promo/actions'
import { BasicFormWrapper } from './component.style'
import loadingAction from '../../../../../../redux/loading/actions'
import ErrorAction from '../../../../../../redux/error/actions'

const { Option } = Select

const { getProducts, getPartners } = PolicyActions
const { getPackageList } = PromoActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction
const { getFileTemplates } = ReconActions

class BasicForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
    }
  }

  componentDidMount () {
    // this.props.getPartners()
    this.props.resetLoadingRedux(['GET_FILE_TEMPLATES'])
    this.props.resetErrorRedux(['GET_FILE_TEMPLATES'])
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.fileTemplatesLoading === false) {
      if (nextProps.fileTemplatesError === false) {
        if (nextProps.fileTemplates.length > 0) {
          this.props.nextStep()
        } else {
          notification['error']({ message: 'No File Templates found' })
        }
      } else {
        notification['error']({ message: 'Error while fetching File templates' })
        this.props.stepStateChange('error')
      }
      this.props.resetLoadingRedux(['GET_FILE_TEMPLATES'])
      this.props.resetErrorRedux(['GET_FILE_TEMPLATES'])
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        this.props.stepStateChange('process')
        let products = get(values, 'product')
        if (products) {
          products.sort()
          values['product'] = products.join(',')
        }
        this.props.getFileTemplates({
          query: {
            ...values
          }
        })
      }
    })
  }

  handleClear = () => {
    this.props.form.resetFields()
  }

  handlePartnerChange = value => {
    this.props.form.resetFields(['product_code', 'package_code'])
    this.props.getProducts({ query: { partner_code: value } })
    this.setState({
      partnerCode: value
    })
  }

  onSelectProduct = e => {
    this.props.getPackageList(e)
  }

  handlePackageSelect = val => {
    const { form, packageList } = this.props

    if (val === 'all') {
      const packageCodeList = map(packageList, 'package_code')
      form.setFieldsValue({ package_code: packageCodeList })
    }
  }

  render () {
    const {
      partners,
      partnersLoading,
      form,
      products,
      fileTemplatesLoading,
      productsLoading
    } = this.props
    const { partnerCode } = this.state
    const { getFieldDecorator } = form
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 4 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 16 }
      }
    }

    return (
      <BasicFormWrapper>
        <Spin spinning={!!fileTemplatesLoading}>
          <Form onSubmit={this.handleSubmit} className='login-form' {...formItemLayout}>
            <Form.Item label='Partner'>
              {getFieldDecorator('partner', {
                rules: [{ required: true, message: 'Please choose partner!' }]
              })(
                <Select
                  placeholder='Partner'
                  className='select'
                  showSearch
                  filterOption={(input, option) => option.props.children.join('').toLowerCase().includes(input.toLowerCase())}
                  onChange={this.handlePartnerChange}
                  loading={!!partnersLoading}
                  disabled={!!partnersLoading}
                >
                  {partners.map(({ name, code }) =>
                    <Option value={code} key={code}>{name} - {code}</Option>
                  )}
                </Select>
              )}
            </Form.Item>
            <Form.Item label='Product'>
              {getFieldDecorator('product')(
                <Select
                  placeholder='Product'
                  className='select'
                  showSearch
                  mode='multiple'
                  onSelect={this.onSelectProduct}
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                  loading={!!productsLoading}
                  disabled={!!productsLoading || partners.length < 1 || !partnerCode}
                >
                  {products.map(({ name, display_name: displayName }) => (<Option value={name} key={displayName}>{displayName}</Option>))}
                </Select>
              )}
            </Form.Item>
            <Row type='flex' justify='space-around'>
              <Button
                type='danger'
                onClick={this.handleClear}
              >
                Clear
              </Button>
              <Button type='primary' htmlType='submit' className='login-form-button'>
                Choose File Template
              </Button>
            </Row>
          </Form>
        </Spin>
      </BasicFormWrapper>
    )
  }
}

BasicForm.propTypes = {
  partners: PropTypes.array.isRequired,
  products: PropTypes.array.isRequired,
  internalUsers: PropTypes.array.isRequired
}

BasicForm.defaultProps = {
  partners: [],
  products: [],
  internalUsers: []
}

const WrappedBasicForm = Form.create()(BasicForm)

export default connect(
  state => ({
    partners: state.Policy.partners,
    products: state.Policy.products,

    partnersLoading: state.Loading.GET_PARTNERS,
    partnersError: state.Error.GET_PARTNERS,

    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,

    packageList: state.PromoDetails.packageLists,
    packageListLoading: state.Loading.GET_COUPON_PACKAGE_LIST,
    packageListError: state.Error.GET_COUPON_PACKAGE_LIST,

    fileTemplatesLoading: state.Loading.GET_FILE_TEMPLATES,
    fileTemplatesError: state.Error.GET_FILE_TEMPLATES,
    fileTemplates: state.Recon.fileTemplates
  }),
  {
    getProducts,
    getPackageList,
    resetLoadingRedux,
    resetErrorRedux,
    getPartners,
    getFileTemplates
  }
)(WrappedBasicForm)
